// Bare-metal test harness. The vector-add function is generated by TileLang.
#include <stdint.h>

#ifndef BLOCK_SIZE
#define BLOCK_SIZE 257
#endif

extern "C" int32_t vector_add_kernel(float *, float *, float *);
extern "C" volatile uint32_t tohost;

namespace {
constexpr uint32_t kHarts = 4;
constexpr float kCanary = -12345.0f;

// Guard cells surround every output tile. All arrays reside in shared SRAM;
// each hart writes only its own input/output range and completion flag.
alignas(64) float input_a[kHarts][BLOCK_SIZE];
alignas(64) float input_b[kHarts][BLOCK_SIZE];
alignas(64) float output[kHarts][BLOCK_SIZE + 2];
volatile uint32_t done[kHarts];

[[noreturn]] void Park() {
  for (;;) {
    asm volatile("nop");
  }
}

[[noreturn]] void Exit(uint32_t code) {
  asm volatile("fence rw, rw" ::: "memory");
  tohost = (code << 1) | 1;
  Park();
}
} // namespace

extern "C" void demo_main(uint32_t hart) {
  if (hart >= kHarts) {
    Exit(1);
  }
  for (uint32_t i = 0; i < BLOCK_SIZE; ++i) {
    input_a[hart][i] =
        static_cast<float>(static_cast<int32_t>((i * 17 + hart * 31) % 127) -
                           63) *
        0.25f;
    input_b[hart][i] =
        static_cast<float>(static_cast<int32_t>((i * 7 + hart * 13) % 61) -
                           30) *
        0.5f;
    output[hart][i + 1] = kCanary;
  }
  output[hart][0] = kCanary;
  output[hart][BLOCK_SIZE + 1] = kCanary;
  if (vector_add_kernel(input_a[hart], input_b[hart], &output[hart][1]) != 0) {
    Exit(2);
  }
  asm volatile("fence rw, w" ::: "memory");
  done[hart] = hart + 1;
  if (hart != 0) {
    Park();
  }

  for (uint32_t h = 0; h < kHarts; ++h) {
    while (done[h] != h + 1) {
      asm volatile("nop");
    }
  }
  asm volatile("fence r, rw" ::: "memory");
  for (uint32_t h = 0; h < kHarts; ++h) {
    if (output[h][0] != kCanary || output[h][BLOCK_SIZE + 1] != kCanary) {
      Exit(3);
    }
    for (uint32_t i = 0; i < BLOCK_SIZE; ++i) {
      // Inputs are small binary fractions, so addition is exact in float32.
      if (output[h][i + 1] != input_a[h][i] + input_b[h][i]) {
        Exit(4 + h * BLOCK_SIZE + i);
      }
    }
  }
  Exit(0);
}
